import { LogLayer, BlankTransport, LogLevel, } from 'loglayer';
const LOG_LEVEL_ORDER = [
    LogLevel.trace,
    LogLevel.debug,
    LogLevel.info,
    LogLevel.warn,
    LogLevel.error,
    LogLevel.fatal,
];
const MAX_LOG_ENTRIES = 10_000;
const CONSOLE_METHOD_MAP = {
    [LogLevel.trace]: 'debug',
    [LogLevel.debug]: 'debug',
    [LogLevel.info]: 'info',
    [LogLevel.warn]: 'warn',
    [LogLevel.error]: 'error',
    [LogLevel.fatal]: 'error',
};
const STORAGE_KEY = 'viam-sdk-log-level';
export const getPersistedLogLevel = () => {
    if (typeof localStorage === 'undefined')
        return null;
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'false')
        return false;
    if (stored === null)
        return null;
    if (LOG_LEVEL_ORDER.includes(stored)) {
        return stored;
    }
    return null;
};
const persistedLevel = getPersistedLogLevel();
const logBuffer = [];
let consoleEnabled = !!persistedLevel;
let consoleLevel = persistedLevel
    ? persistedLevel
    : LogLevel.info;
globalThis.VIAM = {
    ...globalThis.VIAM,
    GRPC_TRACE_LOGGING: consoleLevel === LogLevel.trace && consoleEnabled,
};
let _queryIndex = -1;
const nextQueryId = () => {
    _queryIndex += 1;
    return _queryIndex;
};
const isAtOrAboveLevel = (msgLevel, minLevel) => {
    const msgIdx = LOG_LEVEL_ORDER.indexOf(msgLevel);
    const minIdx = LOG_LEVEL_ORDER.indexOf(minLevel);
    return msgIdx !== -1 && minIdx !== -1 && msgIdx >= minIdx;
};
const consoleTransport = new BlankTransport({
    shipToLogger: ({ logLevel, messages, data, hasData }) => {
        if (!consoleEnabled || !isAtOrAboveLevel(logLevel, consoleLevel)) {
            return messages;
        }
        const method = CONSOLE_METHOD_MAP[logLevel] ?? 'info';
        if (hasData && data) {
            console[method].call(console, ...messages, data);
        }
        else {
            console[method].call(console, ...messages);
        }
        return messages;
    },
});
const cacheTransport = new BlankTransport({
    shipToLogger: ({ logLevel, messages, data, hasData }) => {
        if (logBuffer.length >= MAX_LOG_ENTRIES) {
            logBuffer.shift();
        }
        logBuffer.push({
            timestamp: new Date().toISOString(),
            level: logLevel,
            message: messages.join(' '),
            ...(hasData && data ? { data } : {}),
        });
        return messages;
    },
});
export const logger = new LogLayer({
    transport: [consoleTransport, cacheTransport],
    prefix: '[viam-svelte-sdk]',
    errorSerializer: (err) => ({
        message: err.message,
        name: err.name,
        stack: err.stack,
    }),
});
export const createQueryLogger = (resource, method) => {
    const queryId = nextQueryId();
    return {
        request: (args) => {
            logger.withMetadata({ queryId, resource, method, args }).debug('request');
        },
        response: (response) => {
            logger
                .withMetadata({ queryId, resource, method, response })
                .debug('response');
        },
        error: (error) => {
            logger
                .withError(error)
                .withMetadata({ queryId, resource, method })
                .error('error');
        },
    };
};
const syncGrpcTraceLogging = (level) => {
    globalThis.VIAM = {
        ...globalThis.VIAM,
        GRPC_TRACE_LOGGING: level === LogLevel.trace,
    };
};
export const setSDKLogLevel = (level) => {
    if (level === false) {
        consoleEnabled = false;
    }
    else {
        consoleEnabled = true;
        consoleLevel = level;
    }
    syncGrpcTraceLogging(level);
    if (typeof localStorage !== 'undefined') {
        localStorage.setItem(STORAGE_KEY, String(level));
    }
};
const getSDKLogs = () => [...logBuffer];
const clearSDKLogs = () => {
    logBuffer.length = 0;
};
globalThis.VIAM = {
    ...globalThis.VIAM,
    setSDKLogLevel,
    getSDKLogs,
    clearSDKLogs,
};
export { LogLevel as SDKLogLevel };
